SELECT analytics_order_facts.month, SUM(analytics_order_facts.net_revenue) AS net_revenue FROM analytics_order_facts WHERE analytics_order_facts.year = 2025 AND analytics_order_facts.region = 'South' AND analytics_order_facts.channel = 'online' AND analytics_order_facts.customer_segment = 'mid_market' GROUP BY analytics_order_facts.month ORDER BY analytics_order_facts.month ASC LIMIT 12
